def counting_sort(arr):
    n = len(arr)
    count = [0] * (n + 1)
    for i in range(n):
        count[arr[i]] += 1
    for i in range(1, n + 1):
        count[i] += count[i - 1]
    sorted_arr = [0] * n
    for i in range(n):
        sorted_arr[count[arr[i]] - 1] = arr[i]
    return sorted_arr

