def comb_sort(arr):
    n = len(arr)
    if n <= 1:
        return arr
    else:
        pivot = arr[n//2]
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        return comb_sort(left) + middle + comb_sort(right)

