def count_no_of_ways(n, k):
    # Initialize a 2D array to store the number of ways of painting the fence
    dp = [[0 for _ in range(k)] for _ in range(n)]

    # Initialize the first row and column
    for i in range(k):
        dp[0][i] = 1
    for j in range(n):
        dp[j][0] = 1

    # Fill the rest of the table
    for i in range(1, n):
        for j in range(1, k):
            if i == 1 and j == 1:
                dp[i][j] = 1
            elif i == 1:
                dp[i][j] = dp[i-1][j] + 1
            elif j == 1:
                dp[i][j] = dp[i][j-1] + 1
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1] + 2
    return dp[n-1][k-1]

