def max_sum_increasing_subseq(arr, k, i, j):
    if i == j:
        return arr[i]
    if i > j:
        return 0
    if k == i:
        return arr[i]
    if k == j:
        return arr[j]
    if k > i:
        return max(arr[i], max_sum_increasing_subseq(arr, k, i + 1, j))
    else:
        return max(arr[i], max_sum_increasing_subseq(arr, k, i + 1, j), max_sum_increasing_subseq(arr, k + 1, i, j))

