def no_of_subsequences(arr, k):
    n = len(arr)
    dp = [1 for _ in range(n)]
    for i in range(1, n):
        for j in range(i):
            if arr[i] < arr[j] * k:
                dp[i] = max(dp[i], dp[j] + 1)
    return sum(dp)
